#include <bits/stdc++.h>
using namespace std;
using int64 = long long;

int64 mod;

int64 modpow(int64 a, int64 e) {
    int64 r = 1 % mod;
    while (e) {
        if (e & 1) r = r * a % mod;
        a = a * a % mod;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m >> mod;
    if (m == 1) {
        cout << 0 << "\n";
        return 0;
    }

    // precompute factorials
    vector<int64> fact(n+1), invfact(n+1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i-1] * i % mod;
    invfact[n] = modpow(fact[n], mod-2);
    for (int i = n; i >= 1; --i) invfact[i-1] = invfact[i] * i % mod;

    auto C = [&](int N, int K) -> int64 {
        if (K < 0 || K > N) return 0;
        return fact[N] * invfact[K] % mod * invfact[N-K] % mod;
    };

    int64 ans = 0;
    for (int i = 1; i <= m-1; ++i) {
        int64 term = C(n - i, m - i);
        term = term * (m - i) % mod;
        term = term * 2 % mod;
        ans = (ans + term) % mod;
    }
    ans = ans * fact[m-1] % mod;
    ans = ans * modpow(2, m-1) % mod;
    cout << ans % mod << "\n";
    return 0;
}
